// Private per-account notes. Drafts survive navigation/reload; cloud writes use
// independent versions so editing a note cannot change saved/done records.
export class NoteStore extends EventTarget {
 constructor(account,storage){super();this.account=account;this.storage=storage;this.cache=new Map();this.drafts=new Map();this.pending=new Map();this.sequence=0;this.changedDrafts=new Set();this.availability='loading';this.errors=new Map();this.ready=this.init();}
 emit(id){this.dispatchEvent(new CustomEvent('change',{detail:{id}}));}
 async init(){await this.account.ready;this.owner=this.account.enabled?this.account.user?.id:'local';this.key='pure-private-notes-v1:'+this.owner;if(!this.owner){this.availability='signed-out';return;}try{const v=JSON.parse(this.storage.getItem(this.key)||'{}');this.cache=new Map(Object.entries(v.cache||{}));this.drafts=new Map(Object.entries(v.drafts||{}));for(const d of this.drafts.values())this.sequence=Math.max(this.sequence,d.sequence||0);}catch{this.storageError=true;}if(!this.account.enabled){this.availability='local';this.emit();return;}await this.reload();}
 active(){return !!this.owner&&this.owner===(this.account.enabled?this.account.user?.id:'local');}
 persist(){try{let disk={};try{disk=JSON.parse(this.storage.getItem(this.key)||'{}');}catch{}const drafts={...(disk.drafts||{})},cache={...(disk.cache||{})};for(const id of this.changedDrafts){if(this.drafts.has(id))drafts[id]=this.drafts.get(id);else delete drafts[id];}for(const [id,r] of this.cache)if(!cache[id]||cache[id].version<=r.version)cache[id]=r;this.storage.setItem(this.key,JSON.stringify({cache,drafts}));this.changedDrafts.clear();this.storageError=false;return true;}catch{this.storageError=true;return false;}}
 async reload(){if(!this.active()||!this.account.enabled)return;try{const rows=await this.account.rpc('pp_notes_snapshot');if(!this.active())return;if(!Array.isArray(rows))throw Error('备注数据格式不正确');this.cache=new Map(rows.map(r=>[r.question_id,r]));this.availability='cloud';for(const [id,d] of this.drafts){const r=this.cache.get(id)||{note:'',version:0};if(d.text===r.note){this.drafts.delete(id);this.changedDrafts.add(id);}else if(d.baseVersion!==r.version){d.conflict=true;this.changedDrafts.add(id);}}this.persist();this.emit();}catch(e){if(!this.active())return;this.availability=e.status===404?'migration':'offline';this.lastError=e.message;this.emit();}}
 get(id){const r=this.cache.get(id)||{note:'',version:0},d=this.drafts.get(id);return{text:d?.text??r.note,cloudText:r.note,version:r.version,dirty:!!d,conflict:!!d?.conflict,saving:this.pending.has(id),error:this.errors.get(id)||'',availability:this.availability,storageError:this.storageError};}
 edit(id,text){if(!this.active())throw Error('请重新登录后编辑');if(text.length>10000)throw Error('备注最多10000字');const old=this.drafts.get(id),r=this.cache.get(id)||{note:'',version:0};this.drafts.set(id,{text,baseVersion:old?.baseVersion??r.version,sequence:++this.sequence,conflict:old?.conflict||false});this.errors.delete(id);this.changedDrafts.add(id);this.persist();this.emit(id);}
 async save(id){await this.ready;if(!this.active())throw Error('账户已切换，请重新打开备注');if(this.pending.has(id))return this.pending.get(id);const draft=this.drafts.get(id);if(!draft)return;if(draft.conflict)throw Error('请先对比云端备注，再选择使用云端或保存你的草稿');const job=(async()=>{await Promise.resolve();try{if(this.account.enabled&&this.availability!=='cloud'){await this.reload();if(this.availability!=='cloud')throw Error(this.availability==='migration'?'云端备注尚未启用；草稿已保存在本机，请管理员运行005 SQL':'云端连接暂不可用；草稿已保存在本机，可稍后重试');if(this.drafts.get(id)?.conflict)throw Error('云端已有更新，请对比后选择保留内容');}const sent=this.drafts.get(id);if(!sent)return;const r=this.account.enabled?await this.account.rpc('pp_save_note',{p_question_id:id,p_note:sent.text,p_base_version:sent.baseVersion}):{question_id:id,note:sent.text,version:sent.baseVersion+1};if(!this.active())return;this.cache.set(id,r);const current=this.drafts.get(id);if(current?.sequence===sent.sequence)this.drafts.delete(id);else if(current){current.baseVersion=r.version;current.conflict=false;}this.errors.delete(id);this.changedDrafts.add(id);if(!this.persist()&&!this.account.enabled){this.drafts.set(id,current||sent);this.changedDrafts.add(id);throw Error('浏览器未能保存备注，请复制留存或允许网站存储后重试');}}catch(e){if(this.active()){this.errors.set(id,e.message);if(e.status===409){await this.reload();const current=this.drafts.get(id);if(current){current.conflict=true;this.changedDrafts.add(id);}}this.persist();}throw e;}finally{this.pending.delete(id);this.emit(id);}})();this.pending.set(id,job);this.emit(id);return job;}
 useCloud(id){this.drafts.delete(id);this.errors.delete(id);this.changedDrafts.add(id);this.persist();this.emit(id);}
 async keepDraft(id){const d=this.drafts.get(id);if(!d)return;d.baseVersion=this.cache.get(id)?.version||0;d.conflict=false;d.sequence=++this.sequence;this.changedDrafts.add(id);this.persist();return this.save(id);}
 export(){return {version:1,owner:this.owner,notes:Object.fromEntries([...new Set([...this.cache.keys(),...this.drafts.keys()])].map(id=>[id,this.get(id).text])),drafts:Object.fromEntries(this.drafts)};}
}
